function showToast(t,m) { const tm=el('toast'), ic=el('toast-icon'); if(!tm||!ic)return; tm.classList.remove('hidden'); el('toast-message').innerText=m; ic.className=t==='success'?'fa-solid fa-check text-green-400':'fa-solid fa-xmark text-red-400'; setTimeout(()=>tm.classList.add('hidden'),3000); }
function toggleLoader(a,s) { const txt=el(`btn-${a}-text`), ldr=el(`btn-${a}-loader`); if(txt&&ldr) { txt.classList.toggle('hidden',s); ldr.classList.toggle('hidden',!s); } }
function triggerConfetti() { if(typeof confetti !== 'undefined') confetti({ particleCount:100, spread:70, origin:{y:0.6} }); }
function triggerShake() { const a=el('main-wrapper'); if(a){ a.classList.add('shake-effect'); setTimeout(()=>a.classList.remove('shake-effect'), 500); } }
function toggleFab() { const fc=el('fab-container'); if(fc) fc.classList.toggle('fab-open'); }

const hidePreloaderAndShowAuth = (view='login') => { const authC = el('auth-container'); if(authC) authC.classList.remove('hidden'); switchView(view); const p = el('app-preloader'); if(p) { p.classList.add('opacity-0', 'pointer-events-none'); setTimeout(()=>p.classList.add('hidden'), 700); } };

window.onload = async () => { 
    initAccessibility();
    const bM=el('btn-forecast-monthly'), bY=el('btn-forecast-yearly');
    if(bM) bM.addEventListener('click', ()=>toggleForecastMode('monthly')); if(bY) bY.addEventListener('click', ()=>toggleForecastMode('yearly'));
    
    const fsTimer = setTimeout(() => { const p=el('app-preloader'); if(p && !p.classList.contains('hidden')){ console.warn('Preloader Failsafe'); hidePreloaderAndShowAuth('login'); } }, 5000);
    const params = new URLSearchParams(window.location.search); const code = params.get('code'), role = params.get('role');
    if (code) { if(el('join-code')) el('join-code').value=code; if(role&&el('join-role')) el('join-role').value=role; clearTimeout(fsTimer); hidePreloaderAndShowAuth('join'); return; }
    
    const token = localStorage.getItem('ofl_sa_token');
    if (token) { saToken=token; clearTimeout(fsTimer); if(el('auth-container')) el('auth-container').classList.add('hidden'); if(el('sa-dashboard-container')) el('sa-dashboard-container').classList.remove('hidden'); const p=el('app-preloader'); if(p){ p.classList.add('opacity-0', 'pointer-events-none'); setTimeout(()=>p.classList.add('hidden'),700); } loadSAData(); return; }
    const saved = localStorage.getItem('ofl_session'); 
    if(saved) { try { const s=JSON.parse(saved); if(s&&s.user&&s.user.id) { currentUser=s.user; currentGroup=s.group; clearTimeout(fsTimer); loadDashboard(); return; } } catch(e) { localStorage.removeItem('ofl_session'); } }
    clearTimeout(fsTimer); hidePreloaderAndShowAuth('login');
};

function switchView(view) { ['login','create','join','sa-login'].forEach(v=>{const e=el(`view-${v}`); if(e) e.classList.add('hidden');}); const t=el(`view-${view}`); if(t) t.classList.remove('hidden'); }
function selectType(t) { if(el('create-type')) el('create-type').value=t; if(el('type-family')) el('type-family').className=`flex-1 p-4 rounded-2xl border-2 text-center transition hover:bg-slate-50 ${t==='FAMILY'?'border-blue-500 bg-blue-50 text-blue-600 font-bold':'border-slate-100 text-slate-400 font-bold'}`; if(el('type-business')) el('type-business').className=`flex-1 p-4 rounded-2xl border-2 text-center transition hover:bg-slate-50 ${t==='BUSINESS'?'border-blue-500 bg-blue-50 text-blue-600 font-bold':'border-slate-100 text-slate-400 font-bold'}`; }
function openTosModal(e) { if(e){e.preventDefault(); e.stopPropagation();} const m=el('tos-modal'); if(m) m.classList.remove('hidden'); }
function closeTosModal() { const m=el('tos-modal'); if(m) m.classList.add('hidden'); }

async function handleLogin(e) { e.preventDefault(); forceTourStart=false; authAction('login', {groupCode:val('login-code'), nickname:val('login-nickname'), password:val('login-password')}); }
async function handleCreate(e) { e.preventDefault(); const tos=el('create-tos'); if(tos&&!tos.checked) return showToast('error','יש לאשר את התקנון'); forceTourStart=true; authAction('groups', {type:val('create-type'), groupName:val('create-group-name'), adminEmail:val('create-email'), adminNickname:val('create-nickname'), birthYear:val('create-year'), password:val('create-password')}); }
async function handleJoin(e) { e.preventDefault(); const tos=el('join-tos'); if(tos&&!tos.checked) return showToast('error','יש לאשר את התקנון'); forceTourStart=true; toggleLoader('join',true); try{ const res=await fetch(`${API}/join`, {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({groupCode:val('join-code'), role:val('join-role'), nickname:val('join-nickname'), birthYear:val('join-year'), password:val('join-password')})}); const d=await res.json(); if(d.success){showToast('success','נשלח בהצלחה!'); window.history.replaceState({},document.title,window.location.pathname); switchView('login');}else showToast('error',d.error); }catch(err){showToast('error','שגיאה');}finally{toggleLoader('join',false);} }
async function authAction(endpoint, body) { toggleLoader('login',true); toggleLoader('create',true); try{ const res=await fetch(`${API}/${endpoint}`, {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); const data=await res.json(); if(data.success){ currentUser=data.user; currentGroup=data.group; localStorage.setItem('ofl_session', JSON.stringify({user:currentUser,group:currentGroup})); await loadDashboard(); } else {showToast('error',data.error); hidePreloaderAndShowAuth('login');} } catch(e){showToast('error','שגיאה בחיבור'); hidePreloaderAndShowAuth('login');} finally{toggleLoader('login',false); toggleLoader('create',false);} }

function logout() { localStorage.removeItem('ofl_session'); location.reload(); }
function scrollTabs(direction) { const sc=el('slider-scroll'); if(sc) sc.scrollBy({left: direction*-150, behavior:'smooth'}); }
function switchTab(t) { ['feed','timeclock','tasks','shop','bank','cashflow','academy','members','budget','pantry','recipes','forecast'].forEach(x=>{const e=el(`content-${x}`); if(e) e.classList.add('hidden'); const btn=el(`tab-${x}`); if(btn) btn.classList.remove('tab-active');}); const cT=el(`content-${t}`); if(cT) cT.classList.remove('hidden'); const tT=el(`tab-${t}`); if(tT) tT.classList.add('tab-active'); if(t!=='shop'){const f=el('cart-footer'); if(f) f.classList.add('hidden'); const fc=el('fab-container'); if(fc) fc.classList.remove('fab-lifted');}else{try{renderShopList();}catch(e){}} if(t==='pantry') renderPantry(); if(t==='recipes') renderRecipePantrySelection(); if(t==='forecast') renderForecast(); if(t==='cashflow') renderCashflow(); if(t==='timeclock') fetchTimeclockReport(); }
function updateBatteryUI() { const ind=el('ai-battery-indicator'); if(!ind||!currentGroup) return; ind.classList.remove('hidden','bg-slate-100','text-slate-500','border-slate-200','bg-purple-100','text-purple-600','border-purple-200','bg-red-100','text-red-600','border-red-200','bg-slate-800','text-white','border-transparent'); const isBiz=currentGroup.type==='BUSINESS'; if(currentGroup.is_premium){ ind.innerHTML=isBiz?'<i class="fa-solid fa-bolt"></i> ∞ (Enterprise)':'⚡ ∞ (Pro)'; if(isBiz) ind.classList.add('bg-slate-800','text-white','border-transparent'); else ind.classList.add('bg-gradient-to-r','from-indigo-500','to-purple-500','text-white','border-transparent'); }else{ const tk=currentGroup.ai_tokens!==undefined?currentGroup.ai_tokens:10; ind.innerHTML=`⚡ ${tk}/10`; if(tk>3) ind.classList.add('bg-slate-100','text-slate-600','border-slate-200'); else if(tk>0) ind.classList.add('bg-orange-100','text-orange-600','border-orange-200'); else ind.classList.add('bg-red-100','text-red-600','border-red-200'); } }

function applyDynamicTerminology() {
    if (!currentGroup || currentGroup.type !== 'BUSINESS') return;
    document.body.classList.add('is-business'); document.title = 'Oneflow | מערכת ניהול לעסקים';
    const setH=(id,h)=>{if(el(id)) el(id).innerHTML=h;}; const setT=(id,t)=>{if(el(id)) el(id).innerText=t;};
    setH('tab-shop','רכש 🛒'); setH('tab-pantry','מלאי ציוד 📦'); setH('tab-bank','תקציבים 💳'); setH('tab-budget','בקרה תפעולית 📊'); setH('tab-tasks','משימות עובדים ✅'); setH('tab-academy','מרכז הכשרות 🎓'); setH('tab-members','ניהול צוות 👥');
    if(el('tab-timeclock')) el('tab-timeclock').classList.remove('hidden');
    setT('balance-label','מאזן קופת הארגון'); const cts=el('child-todo-section'); if(cts){const h=cts.querySelector('h3'); if(h) h.innerText='טיקטים ומשימות 🎯';}
    setH('req-title','<i class="fa-solid fa-hourglass-half"></i> בקשות רכש לאישור הנהלה');
    BUDGET_LABELS['allowance']='💰 תקציב אישי לעובדים'; BUDGET_LABELS['tasks']='✅ בונוס טיקטים'; BUDGET_LABELS['academy']='🎓 תמריץ הכשרות';
    const im=el('invite-modal'); if(im){ const h=im.querySelector('h3'); if(h) h.innerText='הזמנת עובדים 👨‍💼'; const p=im.querySelector('p'); if(p) p.innerHTML=`קוד הארגון: <span id="display-group-code" class="font-mono font-bold text-slate-800 bg-slate-100 px-2 py-1 rounded tracking-widest border border-slate-200">---</span>`; const bs=im.querySelectorAll('button'); if(bs.length>=2){bs[0].innerHTML='<i class="fa-solid fa-user-tie"></i> מנהל/ת (הרשאה מלאה)'; bs[1].innerHTML='<i class="fa-solid fa-user"></i> איש/אשת צוות (רגיל)';} }
}

async function loadDashboard() {
    try {
        if(el('auth-container')) el('auth-container').classList.add('hidden'); if(el('dashboard-container')) el('dashboard-container').classList.remove('hidden'); if(el('fab-container')) el('fab-container').classList.remove('hidden');
        const codeBadge = currentGroup.group_code ? `<span class="text-[10px] font-mono bg-blue-100 text-blue-600 px-2 py-0.5 rounded-full mr-2 tracking-widest">קוד: ${currentGroup.group_code}</span>` : '';
        if(el('dash-group-name')) el('dash-group-name').innerHTML = `${currentGroup.name} ${codeBadge}`; if(el('dash-nickname')) el('dash-nickname').innerText = currentUser.nickname || 'משתמש'; 
        applyDynamicTerminology();
        const isAdmin = currentUser.role === 'ADMIN'; const isBiz = currentGroup.type === 'BUSINESS';
        if(isAdmin) { 
            ['admin-panel','btn-add-task','budget-filter','bank-admin-view','academy-admin-view','btn-scan-receipt','admin-shop-tools','btn-budget-insight','btn-pantry-insight','admin-tasks-hint','profile-upgrade-section','admin-members-tools'].forEach(id=>{if(el(id)) el(id).classList.remove('hidden');});
            if(!isBiz && el('req-title')) el('req-title').innerHTML = '<i class="fa-solid fa-hourglass-half"></i> ממתינים לאישור';
            if(el('profile-upgrade-section') && currentGroup.is_premium) el('profile-upgrade-section').innerHTML = `<p class="text-sm font-bold text-green-600 text-center py-2 flex items-center justify-center gap-2"><i class="fa-solid fa-check-circle"></i> ${isBiz ? 'ארגון משודרג ל-Enterprise' : 'החשבון שלכם משודרג ל-Pro'}</p>`;
        } else { 
            ['btn-self-task','bank-child-view','academy-user-view'].forEach(id=>{if(el(id)) el(id).classList.remove('hidden');});
            if(el('profile-upgrade-section')) el('profile-upgrade-section').classList.add('hidden');
            if(el('card-name')) el('card-name').innerText = (currentUser.nickname || '').toUpperCase(); if(el('card-allowance')) el('card-allowance').innerText = `₪${currentUser.allowance_amount || 0}`; if(el('card-interest')) el('card-interest').innerText = `${currentUser.interest_rate || 0}%`; 
            if(el('req-title')) el('req-title').innerHTML = isBiz ? '<i class="fa-solid fa-hourglass-half"></i> בקשות רכש שלי' : '<i class="fa-solid fa-hourglass-half"></i> הבקשות שלי לרכש';
        }
        if(el('btn-add-budget-cat')) el('btn-add-budget-cat').classList.remove('hidden'); updateBatteryUI();
        if (isBiz && !isAdmin) checkPunchStatus();
        if(!pollInterval) pollInterval = setInterval(() => { fetchData(); fetchLoans(); if(isAdmin) fetchPendingUsers(); }, 30000);
        fetchBanners(); await fetchMembers(); if(isAdmin) fetchPendingUsers(); await fetchData(); fetchLoans();
    } catch(e) { console.error('UI Error', e); }
    finally { const p=el('app-preloader'); const fin=async()=>{const sh=await checkGlobalWelcome(); if(!sh){checkAndStartTour(forceTourStart); forceTourStart=false;}}; if(p&&!p.classList.contains('hidden')){p.classList.add('opacity-0','pointer-events-none'); setTimeout(()=>{p.classList.add('hidden'); fin();},700);} else fin(); }
}

async function checkPunchStatus() { try{ const res=await fetch(`${API}/timeclock/status?userId=${currentUser.id}`); currentPunchStatus=await res.json(); updatePunchUI(); } catch(e){ const b=el('btn-punch'); if(b){b.innerText='שגיאה'; b.classList.remove('punch-pulse','punch-btn-in','punch-btn-out'); b.classList.add('bg-slate-200','text-slate-400');} } }
function updatePunchUI() { const b=el('btn-punch'), ic=el('punch-icon'), tx=el('punch-text'), st=el('timeclock-status-text'); if(!b||!currentPunchStatus)return; b.classList.remove('bg-slate-200','text-slate-400','cursor-not-allowed','punch-btn-in','punch-btn-out','punch-pulse'); if(currentPunchStatus.isPunchedIn){ b.classList.add('punch-btn-out','punch-pulse'); if(ic) ic.className='fa-solid fa-door-open text-4xl mb-1'; if(tx) tx.innerText='יציאה'; const t=new Date(currentPunchStatus.punchInTime).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'}); if(st) st.innerHTML=`בעבודה. <span class="text-xs font-normal">כניסה: ${t}</span>`; }else{ b.classList.add('punch-btn-in'); if(ic) ic.className='fa-solid fa-fingerprint text-4xl mb-1'; if(tx) tx.innerText='כניסה'; if(st) st.innerHTML='לא בעבודה.'; } }
async function togglePunch() { const b=el('btn-punch'); if(b&&b.classList.contains('cursor-not-allowed')) return; if(b) b.classList.add('cursor-not-allowed','opacity-70'); try{ const res=await fetch(`${API}/timeclock/punch`, {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:currentUser.id, groupId:currentGroup.id})}); const d=await res.json(); if(d.success){triggerConfetti(); showToast('success', d.isPunchedIn?'החתמת כניסה בהצלחה!':'החתמת יציאה נרשמה.'); checkPunchStatus(); fetchTimeclockReport();}else showToast('error',d.error); }catch(e){showToast('error','שגיאה');} finally{if(b) b.classList.remove('cursor-not-allowed','opacity-70');} }
async function fetchTimeclockReport() { try{ const p=el('tc-date-filter')?el('tc-date-filter').value:'month', uF=el('tc-user-filter')?el('tc-user-filter').value:'all'; const tU=currentUser.role==='ADMIN'?uF:currentUser.id; const res=await fetch(`${API}/timeclock/report?groupId=${currentGroup.id}&userId=${tU}&period=${p}`); const d=await res.json(); const lst=el('timeclock-list'), tot=el('tc-total-hours'); if(!lst||!tot)return; let tm=0, h=''; if(d.length===0){lst.innerHTML='<p class="text-center text-slate-400 py-4">אין דיווחים</p>'; tot.innerText='00:00'; return;} d.forEach(r=>{ const inD=new Date(r.punch_in); let oS='--:--', dur='פעיל', bad='<span class="text-[9px] bg-green-100 text-green-600 px-2 py-0.5 rounded font-bold">פעיל</span>'; if(r.punch_out){ oS=new Date(r.punch_out).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'}); if(r.total_minutes){tm+=parseInt(r.total_minutes); dur=`${String(Math.floor(r.total_minutes/60)).padStart(2,'0')}:${String(r.total_minutes%60).padStart(2,'0')} ש'`;} bad=''; } const uN=(currentUser.role==='ADMIN'&&r.nickname)?`<span class="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded ml-2">${r.nickname}</span>`:''; h+=`<div class="bg-white p-3 rounded-xl border border-slate-100 shadow-sm mb-2 flex justify-between items-center"><div class="flex-1"><div class="flex items-center mb-1"><span class="font-bold text-slate-700 text-sm">${inD.toLocaleDateString('he-IL')}</span>${uN}${bad}</div><div class="text-xs text-slate-500 font-mono tracking-wider"><span class="text-green-600">${inD.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'})}</span> <i class="fa-solid fa-arrow-left text-[8px] mx-1 text-slate-300"></i> <span class="text-red-500">${oS}</span></div></div><div class="text-sm font-bold text-slate-700 bg-slate-50 border border-slate-200 px-3 py-1.5 rounded-lg">${dur}</div></div>`; }); lst.innerHTML=h; tot.innerText=`${String(Math.floor(tm/60)).padStart(2,'0')}:${String(tm%60).padStart(2,'0')}`; }catch(e){} }

window.openBalanceAdjustmentModal = function(id, name) { if(el('adjustment-user-id')) el('adjustment-user-id').value=id; if(el('adjustment-user-name')) el('adjustment-user-name').innerText=`עבור: ${name}`; if(el('adjustment-amount')) el('adjustment-amount').value=''; if(el('adjustment-reason')) el('adjustment-reason').value=''; window.toggleAdjustmentType('deduct'); if(el('balance-adjustment-modal')) el('balance-adjustment-modal').classList.remove('hidden'); };
window.submitBalanceAdjustment = async function() { const amount=parseFloat(val('adjustment-amount')); if(!amount||amount<=0) return showToast('error','סכום לא תקין'); try{ const res=await fetch(`${API}/admin/adjust-balance`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adminId:currentUser.id,groupId:currentGroup.id,childId:val('adjustment-user-id'),type:val('adjustment-type'),amount:amount,reason:val('adjustment-reason')||'הפחתה/בונוס יזום'})}); const d=await res.json(); if(d.success){showToast('success','עודכן!'); if(el('balance-adjustment-modal')) el('balance-adjustment-modal').classList.add('hidden'); fetchData(); fetchMembers();} else showToast('error',d.error); }catch(e){showToast('error','שגיאה');} };

async function fetchMembers() { 
    try {
        if(!currentGroup||!currentGroup.id)return; const res=await fetch(`${API}/group/members?groupId=${currentGroup.id}&requesterId=${currentUser.id}`); membersCache=await res.json(); if(!Array.isArray(membersCache))membersCache=[];
        if(currentUser.role==='ADMIN'){ 
            const isBiz=currentGroup.type==='BUSINESS'; const tL=isBiz?'כל הצוות':'כל המשפחה';
            const f1=el('budget-filter'), f2=el('feed-user-filter'), f3=el('goal-target-user'), f4=el('cashflow-user-filter'), f5=el('tc-user-filter');
            if(f1){const c=f1.value; f1.innerHTML='<option value="all">כללי</option>'; membersCache.forEach(m=>f1.innerHTML+=`<option value="${m.id}">${m.nickname}</option>`); if(c) f1.value=c;}
            if(f2){const c=f2.value; f2.innerHTML=`<option value="all">${tL}</option>`; membersCache.forEach(m=>f2.innerHTML+=`<option value="${m.id}">${m.nickname}</option>`); if(c) f2.value=c;}
            if(f4){const c=f4.value; f4.innerHTML=`<option value="all">${tL}</option>`; membersCache.forEach(m=>f4.innerHTML+=`<option value="${m.id}">${m.nickname}</option>`); if(c) f4.value=c;}
            if(f5){const c=f5.value; f5.innerHTML=`<option value="all">${tL}</option>`; membersCache.forEach(m=>f5.innerHTML+=`<option value="${m.id}">${m.nickname}</option>`); if(c) f5.value=c; f5.classList.remove('hidden');}
            if(f3){const c=f3.value; f3.innerHTML='<option value="">עבור מי? (כללי)</option>'; membersCache.filter(m=>m.role!=='ADMIN').forEach(m=>f3.innerHTML+=`<option value="${m.id}">${m.nickname}</option>`); if(c) f3.value=c;}
        } 
        const ml=el('members-list'); if(ml){ ml.innerHTML=''; membersCache.forEach(m=>{ const ini=m.nickname?m.nickname.charAt(0).toUpperCase():'?'; const dBtn=(currentUser.role==='ADMIN'&&m.id!==currentUser.id)?`<button onclick="deleteUser(${m.id}, '${m.nickname}')" class="mr-3 text-red-400 hover:text-red-600 bg-red-50 w-7 h-7 rounded-full flex items-center justify-center transition"><i class="fa-solid fa-trash text-xs"></i></button>`:''; ml.innerHTML+=`<div class="p-3 flex justify-between items-center border-b border-slate-50 last:border-0"><div class="flex items-center gap-3"><div class="w-9 h-9 bg-slate-100 rounded-full flex items-center justify-center font-bold text-slate-500 text-sm border-2 border-white shadow-sm">${ini}</div><span class="font-bold text-sm text-slate-700">${m.nickname||'משתמש'}</span></div><div class="flex items-center"><span class="text-xs font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded-lg">${m.balance!==null?`₪${m.balance}`:'🔒'}</span>${dBtn}</div></div>`; }); }
        const al=el('bank-accounts-list'); if(al&&currentUser.role==='ADMIN'){ al.innerHTML=''; const ch=membersCache.filter(m=>m.role!=='ADMIN'); if(ch.length===0) al.innerHTML='<p class="text-center text-slate-400 text-sm py-4 bg-slate-50 rounded-2xl">אין משתמשים עדיין.</p>'; else ch.forEach(m=>{ const ini=m.nickname?m.nickname.charAt(0).toUpperCase():'?'; al.innerHTML+=`<div class="bg-white rounded-2xl p-4 shadow-sm border border-slate-50 flex justify-between items-center mb-2"><div class="flex items-center gap-3"><div class="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center font-bold text-lg">${ini}</div><div><h4 class="font-bold text-slate-800 text-sm">${m.nickname}</h4><p class="text-[10px] text-slate-400">₪${m.allowance_amount||0}/תקופה • ${m.interest_rate||0}% ריבית</p><p class="text-xs font-bold text-slate-700 mt-1">יתרה: <span class="text-blue-600">₪${m.balance||0}</span></p></div></div><div class="flex gap-2"><button onclick="openBalanceAdjustmentModal(${m.id}, '${m.nickname}')" class="w-8 h-8 rounded-full bg-blue-50 text-blue-500 flex items-center justify-center"><i class="fa-solid fa-money-bill-transfer text-sm"></i></button><button onclick="openBankSettings(${m.id}, '${m.nickname}', ${m.allowance_amount||0}, ${m.interest_rate||0})" class="w-8 h-8 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center"><i class="fa-solid fa-gear text-sm"></i></button></div></div>`; }); }
    } catch(e){}
}

async function fetchData() {
    try {
        if (!currentGroup || !currentGroup.id || (document.activeElement && document.activeElement.classList.contains('price-input'))) return;
        const res = await fetch(`${API}/data/${currentUser.id}`); const data = await res.json(); if (!data || !data.user) return;
        currentUser.balance = data.user.balance; 
        if(data.group) { currentGroup.ai_tokens=data.group.ai_tokens; currentGroup.is_premium=data.group.is_premium; updateBatteryUI(); const p=el('profile-upgrade-section'); if(p&&currentUser.role==='ADMIN'&&currentGroup.is_premium) p.innerHTML=`<p class="text-sm font-bold text-green-600 text-center py-2 flex items-center justify-center gap-2"><i class="fa-solid fa-check-circle"></i> ${currentGroup.type==='BUSINESS'?'ארגון משודרג ל-Enterprise':'חשבון משודרג ל-Pro'}</p>`; }
        const balEl = el('user-balance'); if(balEl) balEl.innerText = `₪${currentUser.role==='ADMIN' ? membersCache.filter(m=>m.role==='ADMIN').reduce((s,m)=>s+(parseFloat(m.balance)||0),0) : (currentUser.balance||0)}`;
        allTasks = Array.isArray(data.tasks)?data.tasks:[]; bundlesCache=Array.isArray(data.quiz_bundles)?data.quiz_bundles:[]; pantryCache=Array.isArray(data.pantry)?data.pantry:[]; if(data.all_bundles) allBundles=data.all_bundles;
        try{ if(currentUser.role==='ADMIN') renderAdminAcademy(); else {renderMyAssignments(bundlesCache); renderLibrary();} }catch(e){}
        try{ renderTasks(allTasks); renderPantry(); renderRecipePantrySelection(); }catch(e){}
        try{ shoppingListCache=Array.isArray(data.shopping_list)?data.shopping_list:[]; renderShopList(); }catch(e){}
        try{ fetchBudget(); renderForecast(); }catch(e){}
        
        const gl=el(currentUser.role==='ADMIN'?'admin-goals-list':'my-goals-list'), gc=currentUser.role!=='ADMIN'?el('my-goals-container'):null;
        if(gl){ gl.innerHTML=''; if(data.goals&&data.goals.length>0){ if(gc)gc.classList.remove('hidden'); data.goals.forEach(g=>{ const pt=Math.min(100,Math.round((g.current_amount/g.target_amount)*100)); const b=currentUser.role==='ADMIN'?`<span class="text-[10px] bg-slate-100 px-2 py-0.5 rounded block mb-1">${g.owner_name}</span>`:''; const aB=`<button onclick="getFamilAIAdvice(${g.target_user_id||g.user_id}, ${g.id})" class="mt-2 text-[10px] text-purple-600 bg-purple-50 px-2 py-1 rounded border border-purple-100">טיפ AI</button>`; const btnT=currentGroup.type==='BUSINESS'?'העבר תקציב':'הפקד'; gl.innerHTML+=`<div class="bg-white p-4 rounded-2xl shadow-sm border border-slate-50 flex items-start gap-4 mb-2"><div class="radial-progress shrink-0 mt-1" style="--pct:${pt*3.6}deg"><span>${pt}%</span></div><div class="flex-1">${b}<h4 class="font-bold text-slate-800">${g.title}</h4><p class="text-xs text-slate-500 mb-1">₪${g.current_amount} / ₪${g.target_amount}</p><div class="flex gap-2"><button onclick="openDepositModal(${g.id}, '${g.title}')" class="mt-2 bg-indigo-50 text-indigo-600 px-3 py-1 rounded text-xs font-bold"><i class="fa-solid fa-plus"></i> ${btnT}</button>${aB}</div></div></div>`; }); } else { if(gc)gc.classList.add('hidden'); gl.innerHTML='<p class="text-center text-slate-400 text-sm py-4">אין יעדים</p>'; } }
        
        if(currentUser.role!=='ADMIN'&&data.weekly_stats){ const sp=parseFloat(data.weekly_stats.spent).toFixed(1), lm=parseFloat(data.weekly_stats.limit).toFixed(1), pt=lm>0?(sp/lm)*100:0; if(el('card-spend-status')) el('card-spend-status').innerText=`₪${sp} מתוך ₪${lm}`; const bar=el('card-spend-bar'); if(bar){bar.style.width=`${Math.min(100,pt)}%`; bar.className=parseFloat(sp)>parseFloat(lm)?'bg-red-500 h-1.5 rounded-full':'bg-green-400 h-1.5 rounded-full';} if(el('card-spend-msg')) el('card-spend-msg').innerText=parseFloat(sp)>parseFloat(lm)?'חריגה!':'עמידה ביעדים'; }
        
        const lim=200, qId=currentUser.role==='ADMIN'?'all':currentUser.id; const tRes=await fetch(`${API}/transactions?groupId=${currentGroup.id}&userId=${qId}&limit=${lim}`); if(tRes.ok) allTransactions=await tRes.json(); else allTransactions=[];
        try{ renderChildTodo(); buildAndRenderFeed(); const tc=el('tab-cashflow'); if(tc&&tc.classList.contains('tab-active')) renderCashflow(); }catch(e){}
    } catch(e){}
}

async function fetchPendingUsers() { try{ if(!currentGroup||!currentGroup.id)return; const res=await fetch(`${API}/admin/pending-users?groupId=${currentGroup.id}`); const users=await res.json(); const list=el('pending-list'), cont=el('admin-panel'); if(users&&users.length>0){ if(cont)cont.classList.remove('hidden'); if(list){ list.innerHTML=''; users.forEach(u=>{ list.innerHTML+=`<div class="flex justify-between items-center bg-white p-2 rounded-xl mb-1"><span class="text-sm font-bold">${u.nickname}</span><button onclick="approveUser(${u.id})" class="bg-green-500 text-white px-3 py-1 rounded text-xs font-bold">אשר</button></div>`; }); } } else if(cont) cont.classList.add('hidden'); } catch(e){} }
async function fetchLoans() { try{ if(!currentGroup||!currentGroup.id)return; const u=currentUser.role==='ADMIN'?`groupId=${currentGroup.id}`:`userId=${currentUser.id}`; const res=await fetch(`${API}/loans?${u}`); renderLoans(await res.json()); }catch(e){} }
async function fetchBundles() { try{ const res=await fetch(`${API}/data/${currentUser.id}`); const d=await res.json(); if(d.all_bundles) allBundles=d.all_bundles; }catch(e){} }
async function fetchBanners() { try{ const gT=(currentGroup&&currentGroup.type)?currentGroup.type:'FAMILY'; const c=localStorage.getItem(`ofl_banners_${gT}`); if(c) applyBannersToDOM(JSON.parse(c)); const res=await fetch(`${API}/banners?type=${gT}`); const d=await res.json(); if(d.success&&d.banners){ localStorage.setItem(`ofl_banners_${gT}`,JSON.stringify(d.banners)); applyBannersToDOM(d.banners); } }catch(e){} }

function handleAIResponseCheck(data) { if(data.error==='BATTERY_EMPTY'){ const m=el('ai-battery-modal'), u=el('ai-upgrade-section'); if(u) u.classList.toggle('hidden', currentUser.role!=='ADMIN'); if(m) m.classList.remove('hidden'); return false; } return true; }
function closeAiBatteryModal() { const m=el('ai-battery-modal'); if(m) m.classList.add('hidden'); }
function executeWithAIWarning(cb) { if(currentGroup&&currentGroup.is_premium)return cb(); const t=new Date().toLocaleDateString(), d=localStorage.getItem('ofl_ai_warning_dismissed'); if(d===t)return cb(); const m=el('ai-warning-modal'), l=el('ai-warning-left'); if(l)l.innerText=currentGroup.ai_tokens||10; const bc=el('btn-ai-warning-continue'); if(bc){ const n=bc.cloneNode(true); bc.parentNode.replaceChild(n,bc); n.onclick=()=>{ const ds=el('ai-warning-dont-show'); if(ds&&ds.checked) localStorage.setItem('ofl_ai_warning_dismissed',t); if(m)m.classList.add('hidden'); cb(); }; } if(m)m.classList.remove('hidden'); }
function showFamilAIModal(t, txt) { const m=el('familai-advisor-modal'), s=el('familai-modal-subtitle'), l=el('familai-advisor-loading'), te=el('familai-advice-text'), c=el('familai-advisor-content'); if(m)m.classList.remove('hidden'); if(s)s.innerText=t; if(txt){if(l)l.classList.add('hidden'); if(te)te.innerText=txt; if(c)c.classList.remove('hidden');}else{if(l)l.classList.remove('hidden'); if(c)c.classList.add('hidden');} }

async function deleteUser(id, name) { if(!confirm(`האם למחוק את "${name}" לצמיתות?`))return; try{ const res=await fetch(`${API}/users/${id}?adminId=${currentUser.id}`, {method:'DELETE'}); const d=await res.json(); if(d.success){showToast('success','נמחק'); fetchMembers(); fetchData();}else showToast('error',d.error); }catch(e){showToast('error','שגיאה');} }
async function approveUser(id) { await fetch(`${API}/admin/approve-user`, {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:id})}); showToast('success','אושר!'); fetchPendingUsers(); fetchMembers(); }

// --- בניית פיד משותף ---
function buildAndRenderFeed() {
    feedCache=[]; if(currentGroup&&currentGroup.created_at) feedCache.push({type:'system', id:'sys', user_id:0, user_name:'מערכת', date:new Date(currentGroup.created_at), title:'סביבת העבודה הוקמה בהצלחה! 🎉', amount:0});
    if(Array.isArray(allTransactions)) allTransactions.forEach(t=>feedCache.push({type:'transaction', id:t.id, user_id:t.user_id, user_name:t.user_name||(currentUser?currentUser.nickname:''), date:t.date?new Date(t.date):new Date(), title:t.description, amount:t.amount, isIncome:t.type==='income'}));
    if(Array.isArray(allTasks)) allTasks.forEach(t=>{ if(t.status==='approved') feedCache.push({type:'task', id:`t${t.id}`, user_id:t.assigned_to, user_name:t.assignee_name||'', date:t.created_at?new Date(t.created_at):new Date(), title:`משימה: ${t.title}`, amount:t.reward}); });
    feedCache.sort((a,b)=>(b.date&&a.date)?(b.date-a.date):0); const f=el('feed-user-filter'); if(f&&currentUser){ f.classList.toggle('hidden', currentUser.role!=='ADMIN'); } renderUnifiedFeed();
}
function renderUnifiedFeed() {
    const uF=el('feed-user-filter')?el('feed-user-filter').value:'all', dF=el('feed-date-filter')?el('feed-date-filter').value:'all', lst=el('unified-feed-list'); if(!lst)return;
    let f=feedCache; if(currentUser&&currentUser.role!=='ADMIN') f=f.filter(i=>String(i.user_id)===String(currentUser.id)||i.type==='system'); else if(uF!=='all'&&uF!=='') f=f.filter(i=>String(i.user_id)===String(uF)||i.type==='system');
    if(dF!=='all'){ const c=new Date(); c.setMonth(c.getMonth()-parseInt(dF)); f=f.filter(i=>i.date>=c); } f=f.slice(0,30);
    if(f.length===0){ lst.innerHTML='<div class="text-center py-10 bg-white rounded-3xl border border-dashed border-slate-200 mt-2"><p class="text-slate-400">אין פעילות כרגע</p></div>'; return; }
    let h=''; f.forEach(i=>{
        const cC=i.type==='system'?'bg-orange-50':(userColors[i.user_id%userColors.length]||'bg-white'); const uN=i.type!=='system'&&i.user_name?`<span class="text-xs font-bold text-slate-500 block mb-0.5">${i.user_name}</span>`:''; const dStr=i.date.toLocaleDateString('he-IL')+' '+i.date.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'});
        let c=''; if(i.type==='transaction'){ c=`<div class="flex justify-between items-center w-full"><div>${uN}<p class="font-bold text-slate-800">${i.title}</p><p class="text-[10px] text-slate-400">${dStr}</p></div><span class="font-bold ${i.isIncome?'text-green-600':'text-red-600'}" dir="ltr">${i.isIncome?'+':'-'}₪${i.amount}</span></div>`; }
        else if(i.type==='task'){ c=`<div class="flex justify-between items-center w-full"><div>${uN}<p class="font-bold text-slate-700">${i.title}</p><p class="text-[10px] text-slate-400">${dStr}</p></div><span class="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded">₪${i.amount}</span></div>`; }
        else if(i.type==='system'){ c=`<div class="flex justify-between items-center w-full"><div><p class="font-bold text-slate-800">${i.title}</p><p class="text-[10px] text-slate-400">${dStr}</p></div></div>`; }
        h+=`<div class="${cC} p-3.5 rounded-2xl shadow-sm border mb-2 flex items-center">${c}</div>`;
    }); lst.innerHTML=h;
}

// --- SHOPPING ---
async function submitShopItem() { 
    const inp=el('shop-item'), btn=document.querySelector('#shop-modal button.bg-slate-800')||document.querySelector('#shop-modal button.bg-pink-500'); 
    const item=inp?inp.value:'', qty=val('shop-quantity'), est=val('shop-est-price'), unit=val('shop-unit')||"יח'"; 
    if(!item)return; if(btn&&btn.disabled)return; if(btn){btn.disabled=true; btn.innerText='מוסיף...';}
    try{ const res=await fetch(`${API}/shopping/add`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({itemName:item,quantity:qty,unit:unit,estimatedPrice:est,userId:currentUser.id})}); const d=await res.json(); if(d.success){const sm=el('shop-modal'); if(sm)sm.classList.add('hidden'); if(inp)inp.value=''; if(el('shop-est-price'))el('shop-est-price').value=''; if(el('shop-quantity'))el('shop-quantity').value=1; showToast('success','נוסף'); fetchData();} }finally{if(btn){btn.disabled=false; btn.innerText='הוסף';}}
}
function renderShopList() {
    if(document.activeElement&&document.activeElement.classList.contains('price-input'))return; const lst=el('shop-list'), rqL=el('shop-requests-list'), rqC=el('shop-requests-container'); if(!lst)return;
    const act=[], req=[]; shoppingListCache.forEach(i=>{if(i.status==='requested')req.push(i); else act.push(i);});
    if(req.length>0&&rqC&&rqL){ rqC.classList.remove('hidden'); let h=''; req.forEach(i=>{ const a=currentUser.role==='ADMIN'?`<button onclick="updateRow(${i.id},'approve_request')" class="bg-green-100 px-2 py-1 rounded">אשר</button>`:`<span class="text-xs bg-orange-100 px-2 py-1 rounded">ממתין</span>`; h+=`<div class="flex justify-between bg-white p-2 rounded mb-2 border border-orange-200"><div><span class="font-bold text-sm">${i.item_name}</span></div>${a}</div>`; }); rqL.innerHTML=h; } else if(rqC) rqC.classList.add('hidden');
    const ts=el('tab-shop'), isA=ts&&ts.classList.contains('tab-active'), ft=el('cart-footer'), fc=el('fab-container');
    if(act.length===0){ lst.innerHTML='<p class="text-center text-slate-400 py-4">הרשימה ריקה</p>'; if(ft)ft.classList.add('hidden'); if(fc)fc.classList.remove('fab-lifted'); return; }
    if(isA){if(ft)ft.classList.remove('hidden'); if(fc)fc.classList.add('fab-lifted');}else{if(ft)ft.classList.add('hidden'); if(fc)fc.classList.remove('fab-lifted');}
    let h=''; act.forEach(i=>{ const ch=i.status==='in_cart'; const vp=i.estimated_price>0?i.estimated_price:''; const tp=(parseFloat(i.estimated_price)||0)*parseFloat(i.quantity); h+=`<div class="shop-row bg-white p-3 rounded-xl border mb-2 ${ch?'in-cart border-green-200':''}" id="row-${i.id}"><div class="flex items-center gap-3"><input type="checkbox" ${ch?'checked':''} onchange="updateRow(${i.id},'check',this.checked)" class="w-5 h-5 accent-blue-600 rounded cursor-pointer shrink-0"><div class="flex-1 flex justify-between"><span class="font-bold text-sm item-name">${i.item_name}</span><button onclick="deleteItem(${i.id})" class="text-red-400 px-2"><i class="fa-solid fa-trash"></i></button></div></div><div class="flex gap-2 mt-2 items-center"><input type="number" id="price-${i.id}" value="${vp}" ${ch?'':'disabled'} onchange="updateRow(${i.id},'price_save',this.value)" class="price-input w-20 border rounded px-1 text-center font-bold bg-slate-50"><span class="text-xs text-slate-500 font-bold w-16">₪${tp.toFixed(1)}</span><span class="text-xs bg-slate-100 px-2 py-1 rounded w-16 text-center">${i.quantity} ${i.unit||"יח'"}</span><button onclick="toggleMissingLocal(${i.id})" id="btn-missing-${i.id}" class="text-[10px] border px-2 py-1 rounded ml-auto">חסר</button></div></div>`; }); lst.innerHTML=h; calcRunningTotal();
}
async function updateRow(id, type, value) { if(type==='approve_request'){await fetch(`${API}/shopping/update`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({itemId:id,status:'pending'})});}else if(type==='check'){const r=el(`row-${id}`), ip=el(`price-${id}`); if(r){r.classList.toggle('in-cart',value); if(ip)ip.disabled=!value;} await fetch(`${API}/shopping/update`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({itemId:id,status:value?'in_cart':'pending'})});}else if(type==='price_save'){await fetch(`${API}/shopping/update`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({itemId:id,estimatedPrice:value})}); const c=shoppingListCache.find(i=>i.id==id); if(c)c.estimated_price=value;} if(type==='approve_request')fetchData(); else calcRunningTotal(); }
function calcRunningTotal() { let t=0; document.querySelectorAll('.shop-row').forEach(r=>{ const cb=r.querySelector('input[type="checkbox"]'); if(cb&&cb.checked&&!r.classList.contains('missing')){ const id=r.id.replace('row-',''), d=shoppingListCache.find(i=>i.id==id), pi=r.querySelector('.price-input'); t+=((parseFloat(pi?pi.value:0)||0)*(d?parseFloat(d.quantity):1)); } }); const d=el('cart-total-display'); if(d) d.innerText=`₪${t.toFixed(2)}`; }
function toggleMissingLocal(id) { const r=el(`row-${id}`), b=el(`btn-missing-${id}`); if(!r||!b)return; const ms=r.classList.contains('missing'); if(!ms){r.classList.add('missing'); r.classList.remove('in-cart'); const cb=r.querySelector('input[type="checkbox"]'); if(cb){cb.checked=false;cb.disabled=true;} const pr=el(`price-${id}`); if(pr)pr.disabled=true; b.classList.add('bg-orange-100','text-orange-500'); b.innerText='מבוטל';}else{r.classList.remove('missing'); const cb=r.querySelector('input[type="checkbox"]'); if(cb)cb.disabled=false; b.classList.remove('bg-orange-100','text-orange-500'); b.innerText='חסר';} calcRunningTotal(); }
async function submitFinalCheckout() { const st=el('checkout-store'); const store=st?st.value||'ספק':'ספק'; let tot=0; const bI=[], mI=[]; document.querySelectorAll('.shop-row').forEach(r=>{ const id=r.id.replace('row-',''), d=shoppingListCache.find(i=>i.id==id); if(r.classList.contains('missing')) mI.push({id}); else{const cb=r.querySelector('input[type="checkbox"]'); if(cb&&cb.checked){const p=el(`price-${id}`), up=p?(parseFloat(p.value)||0):0, q=d?parseFloat(d.quantity):1, rt=up*q; tot+=rt; bI.push({id,name:d?d.item_name:'פריט',quantity:q,price:rt});}} }); triggerShake(); await fetch(`${API}/shopping/checkout`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({totalAmount:tot,userId:currentUser.id,storeName:store,boughtItems:bI,missingItems:mI})}); const m=el('confirm-checkout-modal'); if(m)m.classList.add('hidden'); triggerConfetti(); showToast('success','הושלם!'); fetchData(); }
function openShopModal() { const m=el('shop-modal'); if(m)m.classList.remove('hidden'); }
function openCheckoutSummary() { let c=0, m=0, t=0; document.querySelectorAll('.shop-row').forEach(r=>{ if(r.classList.contains('missing')) m++; else{const cb=r.querySelector('input[type="checkbox"]'); if(cb&&cb.checked){c++; const id=r.id.replace('row-',''), d=shoppingListCache.find(i=>i.id==id), pi=r.querySelector('.price-input'), up=pi?(parseFloat(pi.value)||0):0, q=d?parseFloat(d.quantity):1; t+=(up*q);}} }); if(c===0&&m===0) return showToast('error','לא סומן כלום'); const sc=el('summ-count'); if(sc)sc.innerText=c; const sm=el('summ-missing'); if(sm)sm.innerText=m; const st=el('summ-total'); if(st)st.innerText=`₪${t.toFixed(2)}`; const mod=el('confirm-checkout-modal'); if(mod)mod.classList.remove('hidden'); }
async function deleteItem(id) { if(!confirm('למחוק פריט זה?'))return; await fetch(`${API}/shopping/delete/${id}`,{method:'DELETE'}); showToast('success','נמחק'); fetchData(); }
async function clearEntireCart() { if(!confirm('לרוקן רשימה?'))return; await fetch(`${API}/shopping/clear/${currentGroup.id}`,{method:'DELETE'}); showToast('success','רוקן'); fetchData(); }

// --- CASHFLOW & BANK ---
function renderCashflow() { const l=el('cashflow-list'); if(!l)return; const uf=el('cashflow-user-filter')?el('cashflow-user-filter').value:'all', df=el('cashflow-date-filter')?el('cashflow-date-filter').value:'all'; let f=allTransactions; if(currentUser.role!=='ADMIN'){ f=f.filter(t=>String(t.user_id)===String(currentUser.id)); if(el('cashflow-user-filter'))el('cashflow-user-filter').classList.add('hidden'); }else{ if(el('cashflow-user-filter'))el('cashflow-user-filter').classList.remove('hidden'); if(uf!=='all') f=f.filter(t=>String(t.user_id)===String(uf)); } if(df!=='all'){ const d=new Date(); d.setMonth(d.getMonth()-parseInt(df)); f=f.filter(t=>new Date(t.date)>=d); } if(f.length===0){l.innerHTML='<p class="text-center text-slate-400 py-4">אין פעולות</p>'; return;} let h=''; f.forEach(t=>{ const inc=t.type==='income', ac=inc?'text-green-600':'text-red-600', px=inc?'+':'-'; const dS=new Date(t.date).toLocaleDateString('he-IL'); const ed=currentUser.role==='ADMIN'?`<button onclick="openEditTransactionModal(${t.id},${t.amount},'${(t.description||'').replace(/'/g,"\\'")}','${t.category}','${t.type}')" class="text-blue-500 bg-blue-50 p-2 rounded-full"><i class="fa-solid fa-pen text-xs"></i></button>`:''; h+=`<div class="bg-white p-3 rounded-xl border mb-2 flex justify-between items-center"><div class="flex-1"><p class="font-bold text-slate-800">${t.description}</p><p class="text-[10px] text-slate-500">${dS} ${t.user_name?`• ${t.user_name}`:''}</p></div><div class="flex items-center gap-3"><span class="font-bold ${ac}" dir="ltr">${px}₪${t.amount}</span>${ed}</div></div>`; }); l.innerHTML=h; }
async function fetchBudget() { const t=currentUser.role==='ADMIN'?(val('budget-filter')||'all'):currentUser.id; const res=await fetch(`${API}/budget/filter?groupId=${currentGroup.id}&targetUserId=${t}`); const d=await res.json(); const l=el('budget-list'); if(!l)return; l.innerHTML=''; d.forEach(b=>{ const pt=b.limit>0?(b.spent/b.limit)*100:0, c=pt>100?'bg-red-500':(pt>80?'bg-orange-500':'bg-green-500'); l.innerHTML+=`<div class="mb-4"><div class="flex justify-between items-end mb-1"><span class="font-bold text-sm text-slate-700">${BUDGET_LABELS[b.category]||b.category} <button onclick="openBudgetModal('${b.category}','${BUDGET_LABELS[b.category]||b.category}',${b.limit})" class="text-[10px] bg-blue-50 text-blue-600 px-2 py-0.5 rounded">ערוך</button></span><span class="text-xs text-slate-500">₪${b.spent} / ${b.limit>0?`₪${b.limit}`:'ללא'}</span></div><div class="w-full bg-slate-100 rounded-full h-2"><div class="${c} h-2 rounded-full" style="width:${Math.min(100,pt)}%"></div></div></div>`; }); }
function openBudgetModal(id, n, l) { el('budget-cat-id').value=id; el('budget-cat-name').innerText=n; el('budget-limit').value=l>0?l:''; el('budget-modal').classList.remove('hidden'); }
async function submitBudgetUpdate() { await fetch(`${API}/budget/update`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({groupId:currentGroup.id,category:val('budget-cat-id'),limit:val('budget-limit'),targetUserId:currentUser.role==='ADMIN'?(val('budget-filter')||'all'):currentUser.id})}); el('budget-modal').classList.add('hidden'); fetchBudget(); }
function openTransactionModal(t) { el('trans-type').value=t; el('trans-modal-title').innerText=t==='income'?'הכנסה':'הוצאה'; const s=el('trans-cat'); s.innerHTML=''; CATEGORIES[t].forEach(c=>s.innerHTML+=`<option value="${c.value}">${c.label}</option>`); el('trans-date').value=new Date().toISOString().split('T')[0]; el('transaction-modal').classList.remove('hidden'); }
async function submitTransaction() { const a=val('trans-amount'); if(!a)return; await fetch(`${API}/transaction`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:currentUser.id,amount:a,description:val('trans-desc')||'פעולה',category:val('trans-cat'),type:val('trans-type'),date:val('trans-date')||new Date().toISOString().split('T')[0]})}); el('transaction-modal').classList.add('hidden'); showToast('success','נשמר!'); fetchData(); }
function openEditTransactionModal(id,amt,desc,cat,type) { el('edit-trans-id').value=id; el('edit-trans-amount').value=amt; el('edit-trans-desc').value=desc; const s=el('edit-trans-cat'); s.innerHTML=''; CATEGORIES[type].forEach(c=>s.innerHTML+=`<option value="${c.value}" ${c.value===cat?'selected':''}>${c.label}</option>`); el('edit-transaction-modal').classList.remove('hidden'); }
async function submitEditTransaction() { await fetch(`${API}/transaction/${val('edit-trans-id')}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:val('edit-trans-amount'),description:val('edit-trans-desc'),category:val('edit-trans-cat'),requesterId:currentUser.id})}); el('edit-transaction-modal').classList.add('hidden'); showToast('success','עודכן!'); fetchData(); }
async function deleteTransaction() { if(!confirm('למחוק?'))return; await fetch(`${API}/transaction/${val('edit-trans-id')}?requesterId=${currentUser.id}`,{method:'DELETE'}); el('edit-transaction-modal').classList.add('hidden'); showToast('success','נמחק!'); fetchData(); }

// --- AI & TASKS ---
function openAIModal() { const m=el('ai-modal'); if(m) m.classList.remove('hidden'); }
async function generateAIQuiz() { executeWithAIWarning(async()=>{ const b=el('btn-ai-gen'); if(b){b.disabled=true; b.innerText='מייצר...';} try{ const r=await fetch(`${API}/academy/ai-generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ageGroup:val('ai-age'),topic:val('ai-topic'),groupId:currentGroup.id})}); const d=await res.json(); if(d.success){showToast('success','מוכן!'); el('ai-modal').classList.add('hidden'); await fetchBundles(); fetchData();} }catch(e){}finally{if(b){b.disabled=false; b.innerText='צור';}} }); }
function openTaskModal(self=false) { const m=el('task-modal'); if(m)m.classList.remove('hidden'); el('task-is-self').value=self; el('task-title').value=''; el('task-reward').value=''; const t=el('task-modal-title'); if(t)t.innerText=self?'ביצוע טיקט/יעד':'יצירת משימה'; }
async function submitTask() { const s=el('task-is-self').value==='true', a=s?currentUser.id:val('task-assignee'), t=val('task-title'), r=val('task-reward'); if(!t)return showToast('error','חסר תיאור'); await fetch(`${API}/tasks`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:t,reward:r||0,assignedTo:a,status:s?'done':'pending'})}); el('task-modal').classList.add('hidden'); triggerConfetti(); showToast('success','נשמר!'); fetchData(); }

function applyBannersToDOM(b) {
    const at=el('app-banner-top'), ab=el('app-banner-bottom');
    const rb=(e,t,l,i)=>{if(!e)return; if(t||i){let h=''; if(i)h+=`<img src="/${i}" class="w-full object-cover block">`; if(t)h+=`<span class="py-3 px-4 block w-full text-center">${t}</span>`; e.innerHTML=h; e.href=l||'#'; e.classList.remove('hidden'); e.classList.add('flex');}else{e.classList.add('hidden'); e.classList.remove('flex');}};
    rb(at, b.banner_top_text, b.banner_top_link, b.banner_top_img); rb(ab, b.banner_bottom_text, b.banner_bottom_link, b.banner_bottom_img);
}
